mapper.select:


    c.del_flag = '0'

        and c.issue_no like concat('%', #{issueNo}, '%')


        and c.person_name like concat('%', #{personName}, '%')


        and c.person_dept like concat('%', #{personDept}, '%')


        and c.violation_type = #{violationType}


        and c.source_type = #{sourceType}


        and c.severity = #{severity}


        and c.handle_type = #{handleType}


        and c.person_id = #{personId}


        and c.status = #{status}


        and date_format(c.violation_date, '%Y%m%d') >= date_format(#{params.beginTime}, '%Y%m%d')


        and date_format(c.violation_date, '%Y%m%d') <= date_format(#{params.endTime}, '%Y%m%d')


order by
    case when c.status in ('3','4') then 1 else 0 end,
    case when c.check_deadline is null then 2
         when c.check_deadline < curdate() then 0
         else 1 end,
    c.create_time desc

mapper.update:
update jc_conduct_issue
violation_date = #{violationDate}, source_type = #{sourceType}, severity = #{severity}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where issue_id = #{issueId}
